const D = { density: .5, energy: .62, speed: 1, scale: 1, hue: 200, x: .5, y: .5, style: 'pipes', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// --- one-time tileset: 16 edge-masks (bit0=N,1=E,2=S,3=W): adjacency tables + weights ---
if (!S.tiles) {
  const pc = new Array(16); for (let m=0;m<16;m++){ let c=0,x=m; while(x){c+=x&1;x>>=1;} pc[m]=c; }
  S.pc = pc;
  const eN=m=>(m&1)?1:0, eE=m=>(m&2)?1:0, eS=m=>(m&4)?1:0, eW=m=>(m&8)?1:0;
  const cN=new Array(16),cE=new Array(16),cS=new Array(16),cW=new Array(16);
  for (let t=0;t<16;t++){ let mN=0,mE=0,mS=0,mW=0;
    for (let n=0;n<16;n++){
      if (eS(n)===eN(t)) mN|=1<<n;   // north neighbour's south edge must match my north
      if (eW(n)===eE(t)) mE|=1<<n;
      if (eN(n)===eS(t)) mS|=1<<n;
      if (eE(n)===eW(t)) mW|=1<<n;
    }
    cN[t]=mN;cE[t]=mE;cS[t]=mS;cW[t]=mW;
  }
  S.cN=cN;S.cE=cE;S.cS=cS;S.cW=cW;
  const w=new Array(16);
  for (let m=0;m<16;m++){ const d=pc[m];
    w[m] = d===0?0.55 : d===1?0.35 : d===2?((m===5||m===10)?1.3:1.55) : d===3?0.9 : 0.55;
  }
  S.w=w; S.full=0xFFFF; S.tiles=true;
}

const u = Math.min(width,height);
const GW = Math.max(4, Math.round(7 + P.density*16));
const GH = Math.max(4, Math.round(GW*height/width));
const N = GW*GH;
const cw = width/GW, ch = height/GH;
const opaque = P.alpha >= 100;
const aMul = P.alpha/100;
const aG = opaque ? 1 : aMul;

function pc16(v){ v=v-((v>>1)&0x5555); v=(v&0x3333)+((v>>2)&0x3333); v=(v+(v>>4))&0x0f0f; return (v+(v>>8))&0x1f; }
function rnd(){ let t = S.rng = (S.rng + 0x6D2B79F5)>>>0; t=Math.imul(t^t>>>15,t|1); t^=t+Math.imul(t^t>>>7,t|61); return ((t^t>>>14)>>>0)/4294967296; }
function allowMask(o, tab){ let a=0; while(o){ const lb=o&-o; a|=tab[31-Math.clz32(lb)]; o&=o-1; } return a; }
function reset(g){
  S.gen=g;
  S.opt=new Int32Array(N).fill(S.full);
  S.tile=new Int8Array(N).fill(-1);
  S.done=false; S.solvedAt=null;
  S.rng=((P.seed*2654435761)+(g*40503)+1)>>>0;
}
function propagate(start){
  const st=[start], opt=S.opt, cN=S.cN,cE=S.cE,cS=S.cS,cW=S.cW;
  while(st.length){
    const c=st.pop(); const gx=c%GW, gy=(c/GW)|0; const o=opt[c];
    if(gy>0){ const nb=c-GW; const no=opt[nb]&allowMask(o,cN); if(no!==opt[nb]){ if(!no)return false; opt[nb]=no; st.push(nb);} }
    if(gx<GW-1){ const nb=c+1; const no=opt[nb]&allowMask(o,cE); if(no!==opt[nb]){ if(!no)return false; opt[nb]=no; st.push(nb);} }
    if(gy<GH-1){ const nb=c+GW; const no=opt[nb]&allowMask(o,cS); if(no!==opt[nb]){ if(!no)return false; opt[nb]=no; st.push(nb);} }
    if(gx>0){ const nb=c-1; const no=opt[nb]&allowMask(o,cW); if(no!==opt[nb]){ if(!no)return false; opt[nb]=no; st.push(nb);} }
  }
  return true;
}
function collapseOne(){
  const opt=S.opt, tile=S.tile, W=S.w;
  let min=99, cand=-1, cnt=0;
  for(let c=0;c<N;c++){ const e=pc16(opt[c]); if(e>1){ if(e<min){min=e;cand=c;cnt=1;} else if(e===min){ cnt++; if(rnd()<1/cnt) cand=c; } } }
  if(cand<0) return 'done';
  let o=opt[cand], sum=0, tmp=o;
  while(tmp){ sum+=W[31-Math.clz32(tmp&-tmp)]; tmp&=tmp-1; }
  let r=rnd()*sum, pick=-1; tmp=o;
  while(tmp){ const t=31-Math.clz32(tmp&-tmp); r-=W[t]; if(r<=0){pick=t;break;} tmp&=tmp-1; }
  if(pick<0) pick=31-Math.clz32(o&-o);
  opt[cand]=1<<pick; tile[cand]=pick;
  if(!propagate(cand)){ reset((S.gen||0)+1); return 'reset'; }
  return 'ok';
}

// --- (re)build grid on size / density / seed change ---
if(!S.opt || S.GW!==GW || S.GH!==GH || S.seedBase!==P.seed){
  S.GW=GW; S.GH=GH; S.seedBase=P.seed; reset(0); S.lastSec=K.section;
}
// clock-reset guard + section regeneration (new dramaturgic pattern each section)
if(S.solvedAt!=null && K.t < S.solvedAt) S.solvedAt = K.t;
if(K.section !== S.lastSec){ S.lastSec=K.section; reset((S.gen||0)+1); }

// --- progressive collapse: a few lowest-entropy cells per frame (this IS the motion) ---
if(!S.done){
  const steps = Math.min(14, Math.max(1, Math.round(1 + P.speed*3 + K.intensity*2 + A.bass*2)));
  for(let s=0;s<steps;s++){ const rr=collapseOne(); if(rr==='done'){ S.done=true; if(S.solvedAt==null) S.solvedAt=K.t; break; } if(rr==='reset') break; }
} else {
  const dwell = 2.5 + (1-K.intensity)*3.5;
  if(S.solvedAt!=null && (K.t - S.solvedAt) > dwell) reset((S.gen||0)+1);
}

// --- render ---
const opt=S.opt, tile=S.tile, pcA=S.pc;
const style=P.style, hb=P.hue;
const flow = K.t*(0.5 + P.speed*0.7);
const sw = cw*(0.14 + P.energy*0.24)*Math.min(1.6, P.scale);

if(opaque) background((hb+30)%360, 35, 9);
// faint circuit grid
push();
stroke((hb+30)%360, 28, 19, (opaque?32:22*aMul)); strokeWeight(1);
for(let i=1;i<GW;i++) line(i*cw,0,i*cw,height);
for(let j=1;j<GH;j++) line(0,j*ch,width,j*ch);
pop();

rectMode(CENTER); strokeJoin(ROUND); strokeCap(ROUND);

function drawConn(cx,cy,list){
  if(style==='knot' && list.length===2){
    const a=list[0], b=list[1];
    const opp = (a[0]===cx && b[0]===cx) || (a[1]===cy && b[1]===cy);
    if(opp){ line(a[0],a[1],b[0],b[1]); }
    else { beginShape(); vertex(a[0],a[1]); quadraticVertex(cx,cy,b[0],b[1]); endShape(); }
  } else {
    for(let k=0;k<list.length;k++) line(cx,cy,list[k][0],list[k][1]);
  }
}
function drawTile(gx,gy,cx,cy,mask){
  const deg=pcA[mask];
  const wv=0.6+0.4*Math.sin((gx+gy)*0.55 - flow + mask*0.4 + A.rms*2.5);
  const th=((hb + mask*22 + (gx+gy)*3)%360+360)%360;
  const hw=cw/2, hh=ch/2;
  const list=[];
  if(mask&1) list.push([cx,cy-hh]);
  if(mask&2) list.push([cx+hw,cy]);
  if(mask&4) list.push([cx,cy+hh]);
  if(mask&8) list.push([cx-hw,cy]);
  let br,sat;
  if(style==='mono'){ sat=0; br=42+wv*52; }
  else if(style==='circuit'){ sat=72; br=44+wv*48; }
  else if(style==='knot'){ sat=58; br=46+wv*44; }
  else if(style==='stained'){ sat=76; br=54+wv*34; }
  else { sat=82; br=50+wv*50; } // pipes
  if(style==='stained'){
    noStroke(); fill(th, sat, br*0.5, 76*aG); rect(cx,cy,cw*0.94,ch*0.94);
  }
  if(deg>0){
    noFill();
    stroke((style==='mono'?0:th), sat*0.7, br, 32*aG); strokeWeight(sw*2.0); drawConn(cx,cy,list);
    stroke((style==='mono'?0:th), sat, Math.min(100,br+18), 96*aG); strokeWeight(sw); drawConn(cx,cy,list);
    if(deg>=3 || style==='circuit'){ noStroke(); fill((style==='mono'?0:th), sat*0.5, Math.min(100,br+26), 95*aG); circle(cx,cy, sw*(deg>=3?1.6:1.15)); }
  }
}

for(let gy=0;gy<GH;gy++) for(let gx=0;gx<GW;gx++){
  const c=gy*GW+gx; const cx=(gx+0.5)*cw, cy=(gy+0.5)*ch;
  let tl=tile[c];
  if(tl<0){ const o=opt[c]; if(pc16(o)===1){ tl=31-Math.clz32(o&-o); } }
  if(tl<0){
    // uncollapsed superposition: faint shimmer
    const sh=0.5+0.5*Math.sin(K.t*2.1 + gx*1.7 + gy*2.3);
    const b=13+sh*11*(0.4+P.energy) + A.mid*10;
    noStroke(); fill(((hb+(gx+gy)*5)%360+360)%360, 40, b, 58*aG);
    rect(cx,cy,cw*0.66,ch*0.66);
    continue;
  }
  drawTile(gx,gy,cx,cy,tl);
}
